CREATE TABLE public.carteiras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),grupo_id uuid NOT NULL REFERENCES public.grupos(id),nome text NOT NULL,tipo text NOT NULL DEFAULT 'financeiro' CHECK(tipo IN ('financeiro','beneficio')),moeda text NOT NULL DEFAULT 'BRL' CHECK(moeda IN ('BRL','USD','EUR')),cor text NOT NULL DEFAULT 'primary' CHECK(cor IN ('primary','credit','debit','saved')),icone text NOT NULL DEFAULT 'wallet' CHECK(icone IN ('wallet','bank','fuel','food','target')),legado text CHECK(legado IN ('dinheiro','alimentacao','refeicao','gasolina')),na_feira boolean NOT NULL DEFAULT false,nas_fixas boolean NOT NULL DEFAULT false,no_painel boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(grupo_id,id),UNIQUE(grupo_id,legado));
GRANT SELECT,INSERT,UPDATE ON public.carteiras TO authenticated; GRANT ALL ON public.carteiras TO service_role;
ALTER TABLE public.carteiras ENABLE ROW LEVEL SECURITY;
CREATE POLICY wallet_read ON public.carteiras FOR SELECT TO authenticated USING(public.e_membro(grupo_id) AND CASE WHEN legado='gasolina' THEN public.module_access('moto') ELSE public.module_access('financas') END);
CREATE POLICY wallet_insert ON public.carteiras FOR INSERT TO authenticated WITH CHECK(public.e_membro(grupo_id) AND public.module_access('financas') AND legado IS NULL);
CREATE POLICY wallet_update ON public.carteiras FOR UPDATE TO authenticated USING(public.e_membro(grupo_id) AND public.module_access('financas') AND (legado IS DISTINCT FROM 'gasolina' OR public.module_access('moto'))) WITH CHECK(public.e_membro(grupo_id) AND public.module_access('financas'));
INSERT INTO public.carteiras(grupo_id,nome,tipo,legado,icone,cor,na_feira,nas_fixas) SELECT g.id,v.nome,v.tipo,v.legado,v.icone,v.cor,v.feira,true FROM public.grupos g CROSS JOIN (VALUES ('Dinheiro','financeiro','dinheiro','wallet','primary',true),('Alimentação','beneficio','alimentacao','food','credit',true),('Refeição','beneficio','refeicao','food','debit',true),('Moto/Gasolina','financeiro','gasolina','fuel','saved',false)) v(nome,tipo,legado,icone,cor,feira);
CREATE FUNCTION public.iniciar_carteiras() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.carteiras(grupo_id,nome,tipo,legado,icone,cor,na_feira,nas_fixas) SELECT NEW.id,v.nome,v.tipo,v.legado,v.icone,v.cor,v.feira,true FROM (VALUES ('Dinheiro','financeiro','dinheiro','wallet','primary',true),('Alimentação','beneficio','alimentacao','food','credit',true),('Refeição','beneficio','refeicao','food','debit',true),('Moto/Gasolina','financeiro','gasolina','fuel','saved',false)) v(nome,tipo,legado,icone,cor,feira); RETURN NEW; END $$;
CREATE TRIGGER initial_wallets AFTER INSERT ON public.grupos FOR EACH ROW EXECUTE FUNCTION public.iniciar_carteiras();
CREATE TABLE public.metas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),grupo_id uuid NOT NULL REFERENCES public.grupos(id),carteira_id uuid NOT NULL,nome text NOT NULL,valor_alvo numeric NOT NULL CHECK(valor_alvo>0),data_limite date,ativa boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(grupo_id,carteira_id) REFERENCES public.carteiras(grupo_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.metas TO authenticated; GRANT ALL ON public.metas TO service_role;
ALTER TABLE public.metas ENABLE ROW LEVEL SECURITY;
CREATE POLICY goals_access ON public.metas FOR ALL TO authenticated USING(public.e_membro(grupo_id) AND public.module_access('financas')) WITH CHECK(public.e_membro(grupo_id) AND public.module_access('financas'));
CREATE TABLE public.cotacoes (moeda text PRIMARY KEY CHECK(moeda IN ('USD','EUR')),valor_brl numeric NOT NULL CHECK(valor_brl>0),data date NOT NULL,consultado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cotacoes TO authenticated; GRANT ALL ON public.cotacoes TO service_role;
ALTER TABLE public.cotacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY exchange_read ON public.cotacoes FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
ALTER TABLE public.lancamentos ADD COLUMN carteira_id uuid,ADD COLUMN transferencia_id uuid,ADD COLUMN categoria text NOT NULL DEFAULT 'Outros',ADD COLUMN fonte text NOT NULL DEFAULT 'manual',ADD FOREIGN KEY(grupo_id,carteira_id) REFERENCES public.carteiras(grupo_id,id);
ALTER TABLE public.contas_fixas ADD COLUMN carteira_id uuid,ADD FOREIGN KEY(grupo_id,carteira_id) REFERENCES public.carteiras(grupo_id,id);
ALTER TABLE public.feira_historico ADD COLUMN carteira_id uuid,ADD FOREIGN KEY(grupo_id,carteira_id) REFERENCES public.carteiras(grupo_id,id);
CREATE INDEX wallet_entries ON public.lancamentos(grupo_id,carteira_id); CREATE INDEX transfer_entries ON public.lancamentos(transferencia_id) WHERE transferencia_id IS NOT NULL;
CREATE FUNCTION public.validar_carteira() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.nome:=btrim(NEW.nome); IF length(NEW.nome) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Informe o nome da carteira'; END IF; IF TG_OP='UPDATE' AND (NEW.grupo_id IS DISTINCT FROM OLD.grupo_id OR NEW.legado IS DISTINCT FROM OLD.legado OR NEW.moeda IS DISTINCT FROM OLD.moeda) THEN RAISE EXCEPTION 'Grupo, vínculo original e moeda não podem mudar'; END IF; IF NEW.legado IN ('alimentacao','refeicao') AND (NEW.tipo<>'beneficio' OR NEW.moeda<>'BRL') THEN RAISE EXCEPTION 'Alimentação e Refeição são benefícios'; END IF; IF NEW.legado IN ('dinheiro','gasolina') AND (NEW.tipo<>'financeiro' OR NEW.moeda<>'BRL') THEN RAISE EXCEPTION 'Carteira original deve permanecer financeira em reais'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_wallet BEFORE INSERT OR UPDATE ON public.carteiras FOR EACH ROW EXECUTE FUNCTION public.validar_carteira();
CREATE FUNCTION public.validar_meta() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE w public.carteiras; BEGIN NEW.nome:=btrim(NEW.nome); SELECT * INTO w FROM public.carteiras WHERE id=NEW.carteira_id AND grupo_id=NEW.grupo_id; IF w.id IS NULL OR w.tipo<>'financeiro' OR w.legado IS NOT DISTINCT FROM 'gasolina' OR length(NEW.nome) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Escolha uma carteira financeira para a meta'; END IF; IF TG_OP='UPDATE' AND NEW.grupo_id IS DISTINCT FROM OLD.grupo_id THEN RAISE EXCEPTION 'Grupo não pode mudar'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_goal BEFORE INSERT OR UPDATE ON public.metas FOR EACH ROW EXECUTE FUNCTION public.validar_meta();
REVOKE ALL ON FUNCTION public.iniciar_carteiras() FROM PUBLIC;
COMMENT ON COLUMN public.lancamentos.conta IS 'Compatibility account key; carteira_id identifies the actual wallet, legacy null rows resolve by account.';
COMMENT ON TABLE public.moto_despesas IS 'Preserved legacy Moto expenses; included in Moto/Gasolina wallet balances and Finanças history.';